# Virtual keyboard identity map.
#
# There is no physical device behind this one -- the reports are built on the
# Windows side from controller buttons and pushed straight to the virtual
# endpoint. So this map does no translation; it exists because the runtime
# expects every virtual device to have one.
#
# ⓘ The listener builds this keyboard's reports itself and hands them to the
# endpoint without this map (keyboard_device.inl): two reports since
# 2026-11-07, the keys and the media key held, each with its report ID. The
# paths below are kept for shape and carry nothing.

[map]
id = virtual_keyboard
version = 1
virtual_device = virtual_keyboard_usb
physical_device = none

[usb.endpoints]
hid_in  = 0x81

[path.input.controller_to_virtual]
trigger = physical.read
source_report = 0
destination_endpoint = 0x81
destination_report = 0
op.1 = bytes.copy source[0..7] -> destination[0..7]
destination_length = 8

[path.output.virtual_to_controller]
# ⓘ Nothing comes back from this device -- the report descriptor declares no
# outputs, so the host has nothing to send. Kept for shape, as the mouse map
# does.
trigger = usb.endpoint.hid_out
source_report = 0
destination_report = 0
op.1 = bytes.copy source[0..7] -> destination[0..7]
destination_length = 8

[advertise]
controller_name = CTM Rebind Keyboard
vendor = ctm
rumble = false
leds = false
adaptive_triggers = false
haptics = false
audio_output = false
audio_input = false
battery = false
